const limit = Number($('Config').first().json.historyPosts) || 12;

const out = ($input.first().json.data || [])
  .filter((p) => p.id && (p.text || '').trim())
  .slice(0, limit)
  .map((p) => ({
    json: { postId: p.id, text: (p.text || '').trim(), timestamp: p.timestamp || '' },
  }));

// Empty account: emit one blank item so the chain still reaches the first post.
if (!out.length) return [{ json: { postId: '', text: '', timestamp: '' } }];

return out;

const cfg = $('Config').first().json;
const maxChars = Number(cfg.maxPostChars) || 280;

// Both nodes emit one item per post in the same order, so indexes line up.
const posts = $('Split posts').all().map((it) => it.json);
const stats = $input.all().map((it) => it.json);

const history = posts
  .map((p, i) => {
    const metrics = {};
    for (const m of (stats[i] && stats[i].data) || []) {
      const v = m.values && m.values[0] ? m.values[0].value : null;
      if (typeof v === 'number') metrics[m.name] = v;
    }
    return {
      date: (p.timestamp || '').slice(0, 10),
      text: p.text || '',
      likes: metrics.likes,
      replies: metrics.replies,
      hasStats: Object.keys(metrics).length > 0,
      score:
        (metrics.likes || 0) + (metrics.replies || 0) * 3 + (metrics.reposts || 0) * 3,
    };
  })
  .filter((h) => h.text);

const label = (h) =>
  h.hasStats ? ` [likes: ${h.likes || 0}, replies: ${h.replies || 0}]` : '';

const best = history
  .filter((h) => h.hasStats && h.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 3);

// Rotation comes from the clock, not a counter: workflow static data is not
// persisted on manual runs. 43200000 ms = 12 h = one slot.
const types = String(cfg.postTypes || '')
  .split('\n')
  .map((l) => l.trim())
  .filter((l) => l && !l.startsWith('#') && !l.startsWith('>'));

const postType = types.length
  ? types[Math.floor(Date.now() / 43200000) % types.length]
  : '';

const system = [
  cfg.playbook,
  '---',
  'PLATFORM LIMITS, these override everything above:',
  `- No longer than ${maxChars} characters including spaces.`,
  '- No markdown: no **, no ##, no bullet lists, no bracketed links.',
  '- No hashtags, no links, no @handles. The offer is referred to only as "the link in my profile", and only when the post type calls for it. Hook posts never mention it.',
  '- Return ONLY the post text: no preamble, no title, no surrounding quotes.',
].join('\n');

const parts = [`Today is ${new Date().toISOString().slice(0, 10)}.`, ''];

if (postType) parts.push('POST TYPE FOR TODAY - ' + postType, '');

if (history.length) {
  parts.push(
    'MY RECENT POSTS, newest first:',
    history.map((h) => `- ${h.date}${label(h)}\n${h.text}`).join('\n\n'),
    '',
    'HOW TO USE THEM:',
    '- Do not repeat these topics and do not open with the same first line.',
    '- This is one account with one line of thought. Build on what I already wrote where it fits, but not in every post.',
    '- A post with noticeably more replies means the topic is alive and can be revisited from another angle.',
    '- If today is an offer, attach it to the problem raised by the most recent hook. If one hook drew far more response than the rest, use that one instead.',
    '',
  );
} else {
  parts.push(
    'This is the first post on the account, there is no history yet.',
    'Do not refer back to anything, even if the post type calls for it.',
    '',
  );
}

if (best.length) {
  parts.push(
    'POSTS WITH THE MOST RESPONSE. Follow their FORM: how the first line is built, the length, the kind of closing question. Not their topic.',
    best.map((h, i) => `${i + 1}.${label(h)} ${h.text}`).join('\n'),
    '',
  );
}

parts.push('Write the next post.');

return [{
  json: {
    model: cfg.model,
    max_tokens: 4000,
    output_config: { effort: 'medium' },
    fallbacks: 'default',
    system,
    messages: [{ role: 'user', content: parts.join('\n') }],
  },
}];

const res = $input.first().json;

if (res.stop_reason === 'refusal') {
  const d = res.stop_details || {};
  throw new Error('The model refused this post: ' + (d.explanation || 'no explanation'));
}

let text = (res.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n')
  .trim();

if (!text) throw new Error('Empty response from the model.');

const maxChars = Number($('Config').first().json.maxPostChars) || 280;

text = text
  .replace(/^```[a-z]*\n?|```$/gim, '')
  .replace(/^[\u0022\u00AB\u201C\u201E\u0027]+|[\u0022\u00BB\u201D\u2018\u0027]+$/g, '')
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/^Post\s*:\s*/i, '')
  .trim();

if (text.length > maxChars) {
  // Cut on a sentence boundary rather than mid-word.
  const cut = text.slice(0, maxChars);
  const stop = Math.max(
    cut.lastIndexOf('.'),
    cut.lastIndexOf('!'),
    cut.lastIndexOf('?'),
    cut.lastIndexOf('\n'),
  );
  text = (stop > maxChars * 0.5 ? cut.slice(0, stop + 1) : cut).trim();
}

return [{ json: { text, length: text.length } }];
